import { Injectable, inject } from '@angular/core';
import { SupabaseClient } from '@supabase/supabase-js';
import { Database } from 'supabase/types/supabase';
import { AlertService } from '../common/alert/alert.service';
import { Note, Verse } from '../common/verse/verse';

@Injectable({
  providedIn: 'root',
})
export class NotesService {
  private readonly alertService = inject(AlertService);
  private readonly supabase = inject<SupabaseClient<Database>>(SupabaseClient);


  async getNotesWithVerse() {
    try {
      const { data, error } = await this.supabase
        .from('notes')
        .select('*, verses(*)')
        .order('id', { ascending: false });

      if (error) {
        throw error;
      }

      return data as NoteWithVerse[];
    } catch (error) {
      this.alertService.createNotice({
        message: 'Failed to fetch notes',
        duration: 5000,
        color: 'danger',
        positionAnchor: 'footer',
      });
      return [];
    }
  }

  async insertNote(note: { verse_id: number; content: string }) {
    try {
      const { data, error } = await this.supabase
        .from('notes')
        .insert(note)
        .select()
        .single();

      if (error) {
        throw error;
      }

      return data as Note;
    } catch (error) {
      this.alertService.createNotice({
        message: 'Failed to insert note',
        duration: 5000,
        color: 'danger',
        positionAnchor: 'footer',
      });
      throw error;
    }
  }

  async updateNote(id: number, content: string) {
    try {
      const { data, error } = await this.supabase
        .from('notes')
        .update({ content })
        .eq('id', id)
        .select()
        .single();

      if (error) {
        throw error;
      }

      return data as Note;
    } catch (error) {
      this.alertService.createNotice({
        message: 'Failed to update note',
        duration: 5000,
        color: 'danger',
        positionAnchor: 'footer',
      });
      throw error;
    }
  }

  async deleteNote(id: number) {
    try {
      const { error } = await this.supabase
        .from('notes')
        .delete()
        .eq('id', id);

      if (error) {
        throw error;
      }
    } catch (error) {
      this.alertService.createNotice({
        message: 'Failed to delete note',
        duration: 5000,
        color: 'danger',
        positionAnchor: 'footer',
      });
      throw error;
    }
  }
}

export type NoteWithVerse = Note & {
  verses: Verse;
};
