import { Directive, inject, input, OnDestroy, output } from '@angular/core';
import { NgModel } from '@angular/forms';
import { distinctUntilChanged, skip, Subscription } from 'rxjs';
import { TimerService } from 'src/app/common/timer/timer.service';

@Directive({
  selector: '[ngModelChangeDebounced]',
})
export class NgModelChangeDebouncedDirective implements OnDestroy {
  // Signal inputs/outputs
  ngModelChangeDebounced = output<any>();
  ngModelChangeDebounceTime = input<number>(500); // optional, 500 default

  private subscription: Subscription;
  private ngModel = inject(NgModel);
  private timerService = inject(TimerService);

  constructor() {
    this.subscription = this.ngModel.control.valueChanges.pipe(
      skip(1), // skip initial value
      distinctUntilChanged(),
      this.timerService.debounceTime(this.ngModelChangeDebounceTime())
    ).subscribe((value) => this.ngModelChangeDebounced.emit(value));
  }

  ngOnDestroy() {
    this.subscription.unsubscribe();
  }
} 