import { CommonModule, DatePipe } from '@angular/common';
import {
  Component,
  computed,
  effect,
  inject,
  input,
  output,
  signal,
  viewChild,
} from '@angular/core';
import { FormsModule } from '@angular/forms';
import { RouterLink } from '@angular/router';
import {
  IonCard,
  IonCardContent,
  IonCardHeader,
  IonCardSubtitle,
  IonCardTitle,
  IonSpinner,
  IonTextarea,
} from '@ionic/angular/standalone';
import { AlertService } from 'src/app/common/alert/alert.service';
import { TimerService } from 'src/app/common/timer/timer.service';
import { NotesService } from 'src/app/notes/notes.service';
import { NoteAttachment } from '../attachment';
import { NgModelChangeDebouncedDirective } from './ng-model-change-debounced.directive';

@Component({
  selector: 'app-note-attachment-card',
  templateUrl: './note-attachment-card.component.html',
  styleUrls: ['./note-attachment-card.component.scss'],
  imports: [
    IonCardSubtitle,
    IonCardTitle,
    IonCardHeader,
    IonCard,
    IonCardContent,
    DatePipe,
    RouterLink,
    IonTextarea,
    IonSpinner,
    FormsModule,
    CommonModule,
    NgModelChangeDebouncedDirective,
  ],
})
export class NoteAttachmentCardComponent {
  readonly textarea = viewChild(IonTextarea);

  // Signal inputs
  attachment = input.required<NoteAttachment>();
  routerLink = input<string[]>();
  title = input<string>('Attachment');
  isEditing = input<boolean>(false); // Now settable from parent

  // Signal outputs
  remove = output<NoteAttachment>();
  update = output<NoteAttachment>();
  isEditingChange = output<boolean>(); // Emit when editing state changes

  // Internal signals
  private _isEditingInternal = signal<boolean>(false);
  isSaving = signal<boolean>(false);
  lastSaved = signal<Date | null>(null);

  // Computed signals
  currentIsEditing = computed(() => {
    // Use parent input if provided, otherwise use internal state
    return this.isEditing() || this._isEditingInternal();
  });

  // Services
  private alertService = inject(AlertService);
  private notesService = inject(NotesService);
  private timerService = inject(TimerService);

  closeIcon = 'node_modules/openmoji/color/svg/E24E.svg'; // ⏹️ Close Button

  editIcons = {
    checkmark: 'node_modules/openmoji/color/svg/2705.svg', // ✅ Check Mark Button
    pencil: 'node_modules/openmoji/color/svg/270F.svg', // ✏️ Pencil
  };

  constructor() {
    // Effect to handle focus when entering edit mode
    effect(() => {
      if (this.currentIsEditing()) {
        // Use TimerService for the delay
        this.timerService.timer(0).subscribe(() => {
          this.focusTextarea();
        });
      }
    });
  }

  private async focusTextarea() {
    const textareaEl = await this.textarea()?.getInputElement();
    if (textareaEl) {
      textareaEl.focus();
      // Set cursor position to end of text
      textareaEl.setSelectionRange(
        textareaEl.value.length,
        textareaEl.value.length
      );
    }
  }

  async toggleEdit(event: Event) {
    event.stopPropagation();
    event.preventDefault();
    const newEditingState = !this.currentIsEditing();
    this._isEditingInternal.set(newEditingState);
    this.isEditingChange.emit(newEditingState);
  }

  async onContentChange(content: string) {
    await this.saveContent(content);
  }

  private async saveContent(content: string) {
    const currentAttachment = this.attachment();
    if (content === currentAttachment.content) return;

    this.isSaving.set(true);
    try {
      const updatedNote = await this.notesService.updateNote(
        currentAttachment.id,
        content
      );

      // Update the attachment content
      const updatedAttachment = { ...currentAttachment, content };
      this.lastSaved.set(new Date());
      this.update.emit(updatedAttachment);
    } finally {
      // Use TimerService for the minimum display time
      await this.timerService.timer(1000).toPromise();
      this.isSaving.set(false);
    }
  }

  async removeAttachment(event: Event) {
    event.stopPropagation();
    event.preventDefault();
    await this.alertService.presentAlert({
      header: 'Remove Attachment',
      message: 'Are you sure you want to remove this attachment?',
      buttons: [
        {
          text: 'Cancel',
          role: 'cancel',
        },
        {
          text: 'Yes',
          handler: () => {
            this.remove.emit(this.attachment());
          },
        },
      ],
    });
  }
}
